using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        result.Log("Homesteader.UI.HudState reachable: " + typeof(Homesteader.UI.HudState).FullName);
        var hs = Homesteader.UI.HudState.Active;
        result.Log("HudState.Toolbar.Count = " + hs.Toolbar.Count);
        result.Log("HudState.Vitals.Wellness.Value = " + hs.Vitals[Homesteader.UI.VitalId.Wellness].Value);
        result.Log("HudState.Resources[Water].Amount = " + hs.Resources[Homesteader.UI.ResourceId.Water].Amount);
        var ts = Homesteader.UI.TimeSystem.Instance;
        result.Log("TimeSystem.CycleMinute() = " + ts.CycleMinute() + " (at start)");
        ts.SetSpeed(Homesteader.UI.HomesteaderSpeed.Speed3X);
        ts.Tick(2.0f);
        result.Log("After 2s at 3x: CycleMinute() = " + ts.CycleMinute());
        ts.SetSpeed(Homesteader.UI.HomesteaderSpeed.Speed1X);
        ts.Tick(60.0f);
        var snap = ts.Snapshot();
        result.Log("After 60s at 1x: dayOfYear=" + snap.DayOfYear + ", cycleMinute=" + snap.CycleMinute);

        // Test HudBindings type is reachable.
        result.Log("Homesteader.UI.HudBindings type: " + typeof(Homesteader.UI.HudBindings).FullName);
    }
}
